import test from 'node:test';
import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
import {validateQuestionBundle} from '../src/question-bundle-gate.js';
const sha=s=>createHash('sha256').update(s).digest('hex');
const asset=(id,kind)=>({id,kind,page:5,sha256:sha(id),crop:{x0:1,y0:2,x1:50,y1:60}});
const assets=[asset('unnumbered-figure','figure'),asset('table-a','table'),asset('unnumbered-table','table')];
const bundle={schema:'official-question-bundle-v1',key:'測量士補:2025:午前:7',source:{questionPdfSha256:sha('q'),answerPdfSha256:sha('a'),pages:[5]},body:'問題本文',assets,choices:['1','2','3','4','5'],answer:{number:3,evidenceSha256:sha('official-cell')},layout:['body',...assets.map(a=>a.id),'choices','answer-control']};
const manifest={key:bundle.key,questionPdfSha256:bundle.source.questionPdfSha256,answerPdfSha256:bundle.source.answerPdfSha256,pages:[5],bodySha256:sha(bundle.body),choiceSha256:bundle.choices.map(sha),answerNumber:3,answerEvidenceSha256:bundle.answer.evidenceSha256,assets:structuredClone(assets),reviewStatus:'approved',allVisualsAccountedFor:true,answerCellChecked:true,textChecked:true,displayChecked:true};
test('multiple numbered and unnumbered figures and tables supported',()=>assert.equal(validateQuestionBundle(bundle,manifest).ok,true));
test('missing figure rejected',()=>assert.equal(validateQuestionBundle({...bundle,assets:assets.slice(1)},manifest).reason,'ASSET_COUNT_MISMATCH'));
test('wrong figure swapped rejected',()=>assert.equal(validateQuestionBundle({...bundle,assets:[assets[1],assets[0],assets[2]]},manifest).reason,'ASSET_ID_OR_KIND_MISMATCH'));
test('wrong question ID rejected',()=>assert.equal(validateQuestionBundle({...bundle,key:'測量士補:2025:午前:8'},manifest).reason,'QUESTION_ID_MISMATCH'));
test('wrong answer rejected',()=>assert.equal(validateQuestionBundle({...bundle,answer:{...bundle.answer,number:2}},manifest).reason,'ANSWER_MISMATCH'));
test('wrong page rejected',()=>assert.equal(validateQuestionBundle({...bundle,source:{...bundle.source,pages:[6]}},manifest).reason,'PAGE_BOUNDARY_MISMATCH'));
test('incorrect placement rejected',()=>assert.equal(validateQuestionBundle({...bundle,layout:['body','choices',...assets.map(a=>a.id),'answer-control']},manifest).reason,'LAYOUT_MISMATCH'));
test('pending independent review rejected',()=>assert.equal(validateQuestionBundle(bundle,{...manifest,reviewStatus:'pending'}).reason,'REVIEW_INCOMPLETE'));
test('unreviewed visual rejected',()=>assert.equal(validateQuestionBundle(bundle,{...manifest,allVisualsAccountedFor:false}).reason,'REVIEW_INCOMPLETE'));
test('text mutation rejected',()=>assert.equal(validateQuestionBundle({...bundle,body:'別の問題'},manifest).reason,'BODY_MISMATCH'));
